import random
import json
from typing import List, Dict

# Import the problems and reduction
from problems import ThreeSat, ThreeColoring
import reduce

def solve_3sat(instance: Dict) -> bool:
    m = instance["num_vars"]
    clauses: List[List[int]] = instance["clauses"]
    # iterate all assignments
    for bits in range(1 << m):
        ok = True
        for clause in clauses:
            clause_ok = False
            for lit in clause:
                var = abs(lit) - 1
                val = (bits >> var) & 1  # 1 means true
                if lit > 0 and val == 1:
                    clause_ok = True
                if lit < 0 and val == 0:
                    clause_ok = True
            if not clause_ok:
                ok = False
                break
        if ok:
            return True
    return False

def solve_3coloring(instance: Dict) -> bool:
    n = instance["n"]
    edges = [(u, v) for u, v in instance["edges"]]
    # try all colorings using 0,1,2
    colors = [0] * n
    def backtrack(v: int) -> bool:
        if v == n:
            return True
        for c in range(3):
            ok = True
            for (u, w) in edges:
                if u == v and colors[w] == c:
                    ok = False
                    break
                if w == v and colors[u] == c:
                    ok = False
                    break
